    }
    if (window->pending_count >= PLATFORM_EVENT_QUEUE_CAP) return false;
    platform_event_node *node = malloc(sizeof(*node));
    if (node == NULL) {
        return false;
    }
    node->value = *event;
    node->next = NULL;
    if (window->last == NULL) {
        window->first = node;
    } else {
        window->last->next = node;
    }
    window->last = node;
    window->pending_count++;
    return true;
}

